package scp_candidate.Mining_Threat_Retreat_Supervision

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Threat_Qualification_Api {
  def id: Art.BridgeId
  def threat_sample_Id : Art.PortId
  def threat_validity_Id : Art.PortId
  def disposition_mining_Id : Art.PortId
  def disposition_defense_Id : Art.PortId
  def disposition_mobility_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var threat_validity: Mining_Threat_Retreat_Supervision.ThreatValidityValue = $

  def put_threat_validity(value : Mining_Threat_Retreat_Supervision.ThreatValidityValue) : Unit = {
    Contract(
      Modifies(threat_validity),
      Ensures(
        threat_validity == value
      )
    )
    Spec {
      threat_validity = value
    }

    Art.putValue(threat_validity_Id, Mining_Threat_Retreat_Supervision.ThreatValidityValue_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var disposition_mining: Mining_Threat_Retreat_Supervision.ThreatDispositionValue = $

  def put_disposition_mining(value : Mining_Threat_Retreat_Supervision.ThreatDispositionValue) : Unit = {
    Contract(
      Modifies(disposition_mining),
      Ensures(
        disposition_mining == value
      )
    )
    Spec {
      disposition_mining = value
    }

    Art.putValue(disposition_mining_Id, Mining_Threat_Retreat_Supervision.ThreatDispositionValue_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var disposition_defense: Mining_Threat_Retreat_Supervision.ThreatDispositionValue = $

  def put_disposition_defense(value : Mining_Threat_Retreat_Supervision.ThreatDispositionValue) : Unit = {
    Contract(
      Modifies(disposition_defense),
      Ensures(
        disposition_defense == value
      )
    )
    Spec {
      disposition_defense = value
    }

    Art.putValue(disposition_defense_Id, Mining_Threat_Retreat_Supervision.ThreatDispositionValue_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var disposition_mobility: Mining_Threat_Retreat_Supervision.ThreatDispositionValue = $

  def put_disposition_mobility(value : Mining_Threat_Retreat_Supervision.ThreatDispositionValue) : Unit = {
    Contract(
      Modifies(disposition_mobility),
      Ensures(
        disposition_mobility == value
      )
    )
    Spec {
      disposition_mobility = value
    }

    Art.putValue(disposition_mobility_Id, Mining_Threat_Retreat_Supervision.ThreatDispositionValue_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Threat_Qualification_Initialization_Api (
  val id: Art.BridgeId,
  val threat_sample_Id : Art.PortId,
  val threat_validity_Id : Art.PortId,
  val disposition_mining_Id : Art.PortId,
  val disposition_defense_Id : Art.PortId,
  val disposition_mobility_Id : Art.PortId) extends Threat_Qualification_Api

@datatype class Threat_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val threat_sample_Id : Art.PortId,
  val threat_validity_Id : Art.PortId,
  val disposition_mining_Id : Art.PortId,
  val disposition_defense_Id : Art.PortId,
  val disposition_mobility_Id : Art.PortId) extends Threat_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var threat_sample: Mining_Threat_Retreat_Supervision.ThreatSampleValue = $

  def get_threat_sample() : Option[Mining_Threat_Retreat_Supervision.ThreatSampleValue] = {
    Contract(
      Ensures(
        Res == Some(threat_sample)
      )
    )
    val value : Option[Mining_Threat_Retreat_Supervision.ThreatSampleValue] = Art.getValue(threat_sample_Id) match {
      case Some(Mining_Threat_Retreat_Supervision.ThreatSampleValue_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port threat_sample.  Expecting 'Mining_Threat_Retreat_Supervision.ThreatSampleValue_Payload' but received ${v}")
        None[Mining_Threat_Retreat_Supervision.ThreatSampleValue]()
      case _ => None[Mining_Threat_Retreat_Supervision.ThreatSampleValue]()
    }
    return value
  }
}
